    44	                std::env::var("XDG_CURRENT_DESKTOP").unwrap_or_else(|_| "unknown".into()),
    45	                std::env::var("XDG_SESSION_TYPE").unwrap_or_else(|_| "unknown".into()),
    46	            );
    47	            logger.record("startup_environment", &environment_code);
