    11	#[derive(Debug)]
    12	pub struct DiagnosticLogger {
    13	    file: Option<Mutex<File>>,
    14	}
    15	
    16	impl DiagnosticLogger {
    17	    pub fn open(log_dir: &Path) -> Self {
    18	        let file = fs::create_dir_all(log_dir)
    19	            .and_then(|_| {
    20	                OpenOptions::new()
    21	                    .create(true)
    22	                    .append(true)
    23	                    .mode(0o600)
    24	                    .open(log_dir.join("searchis.log"))
    25	            })
    26	            .ok();
    27	        if let Some(file) = &file {
    28	            let _ = file.set_permissions(fs::Permissions::from_mode(0o600));
    29	        }
    30	        Self {
    31	            file: file.map(Mutex::new),
    32	        }
    33	    }
    34	
    35	    pub fn record(&self, operation: &str, code: &str) {
    36	        let line = format!(
    37	            "{} app={} operation={} code={}\n",
    38	            chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, true),
    39	            env!("CARGO_PKG_VERSION"),
    40	            operation,
    41	            code,
    42	        );
    43	        eprint!("{line}");
    44	        if let Some(file) = &self.file {
    45	            if let Ok(mut file) = file.lock() {
    46	                let _ = file.write_all(line.as_bytes()).and_then(|_| file.flush());
    47	            }
    48	        }
    49	    }
    50	
    51	    pub fn failure(&self, operation: &str, error: &AppError) {
    52	        self.record(operation, error.code);
    53	    }
    54	}

