    10	pub fn normalize_key(value: &str) -> Result<String, AppError> {
    11	    let mut normalized = String::new();
    12	    let mut pending_separator = false;
    13	
    14	    for ch in value.trim().chars() {
    15	        if ch.is_whitespace() {
    16	            pending_separator = !normalized.is_empty();
    17	            continue;
    18	        }
    19	        if pending_separator {
    20	            normalized.push('-');
    21	            pending_separator = false;
    22	        }
    23	        for lower in ch.to_lowercase() {
    24	            normalized.push(lower);
    25	        }
    26	    }
    27	
    28	    let length = normalized.chars().count();
    29	    if !(1..=64).contains(&length) {
    30	        return Err(AppError::validation("key", "Key 长度必须为 1–64 个字符。"));
    31	    }
    32	    if !normalized
    33	        .chars()
    34	        .all(|ch| ch.is_alphanumeric() || matches!(ch, '-' | '_' | '.'))
    35	    {
    36	        return Err(AppError::validation(
    37	            "key",
    38	            "Key 只能包含 Unicode 字母、数字、-、_ 或 .。",
    39	        ));
    40	    }
    41	    Ok(normalized)
    42	}
