291	fn apply_key(connection: &Connection, key: &[u8]) -> Result<(), AppError> {
292	    let key_literal = format!("x'{}'", hex::encode(key));
293	    connection
294	        .pragma_update(None, "key", key_literal)
295	        .map_err(|_| db_open_error("无法应用数据库密钥。请恢复正确密钥后重试。"))
296	}
297	
298	fn verify_cipher(connection: &Connection) -> Result<(), AppError> {
299	    let cipher_version: Option<String> = connection
300	        .query_row("PRAGMA cipher_version", [], |row| row.get(0))
301	        .optional()
302	        .map_err(|_| db_open_error("SQLCipher 初始化失败。禁止使用明文数据库。"))?;
303	    if cipher_version.as_deref().unwrap_or_default().is_empty() {
304	        return Err(db_open_error(
305	            "当前构建未启用 SQLCipher，已拒绝创建明文数据库。",
306	        ));
307	    }
308	    connection
309	        .query_row("SELECT count(*) FROM sqlite_master", [], |_| Ok(()))
310	        .map_err(|_| db_open_error("数据库密钥错误或数据库文件已损坏。请恢复正确密钥或备份。"))
311	}
312	
313	fn migrate(connection: &mut Connection) -> Result<(), AppError> {
314	    let transaction = connection
315	        .transaction()
316	        .map_err(|_| db_open_error("无法启动数据库迁移事务。原数据未修改。"))?;
317	    transaction.execute_batch(
318	        "CREATE TABLE IF NOT EXISTS metadata (
319	            schema_version INTEGER NOT NULL CHECK (schema_version >= 1)
320	         );
321	         CREATE TABLE IF NOT EXISTS snippets (
322	            id TEXT PRIMARY KEY NOT NULL,
323	            key TEXT NOT NULL,
324	            normalized_key TEXT NOT NULL,
325	            title TEXT NOT NULL,
326	            content TEXT NOT NULL,
327	            aliases TEXT NOT NULL,
328	            tags TEXT NOT NULL,
329	            pinned INTEGER NOT NULL CHECK (pinned IN (0, 1)),
330	            sensitive INTEGER NOT NULL CHECK (sensitive IN (0, 1)),
331	            usage_count INTEGER NOT NULL DEFAULT 0 CHECK (usage_count >= 0),
332	            last_used_at TEXT,
333	            created_at TEXT NOT NULL,
334	            updated_at TEXT NOT NULL CHECK (updated_at >= created_at),
335	            deleted_at TEXT,
336	            revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1)
337	         );
338	         CREATE UNIQUE INDEX IF NOT EXISTS snippets_normalized_key_unique ON snippets(normalized_key);
339	         CREATE TABLE IF NOT EXISTS create_requests (
340	            request_id TEXT PRIMARY KEY NOT NULL,
341	            snippet_id TEXT NOT NULL REFERENCES snippets(id),
342	            request_fingerprint TEXT NOT NULL,
